import json
with open('json/posts.json') as f:
    data = json.load(f)
print('Keys:', list(data.keys()))
for k in list(data.keys())[:5]:
    v = data[k]
    if isinstance(v, dict):
        print(f'{k}: dict with keys {list(v.keys())[:5]}')
    elif isinstance(v, list):
        print(f'{k}: list of {len(v)}')
        if len(v) > 0:
            print(f'  First: {v[0]}')
    else:
        print(f'{k}: {type(v)} = {v}')

